"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[15586],{15586:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/the-tragedy-of-y.png\\"\\n          title=\\"The Tragedy of Y\\"\\n          author=\\"Ellery Queen\\"\\n          publisher=\\"Black Forest\\"\\n          publishedDate=\\"2013-05-13\\"\\n          isbn=\\"9788952768711\\"\\n          rating=4.5\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\nIt is one of the ```world\'s top three mystery novels```.  \\nIt\'s a very famous work, but I hadn\'t picked it up for a while until I happened to see it at Aladin Secondhand Bookstore and decided to read it.  \\n<br>\\nThe direction the case flows and the detective\'s reasoning are not forced and are convincing.  \\nAlso, the identity of the culprit in the twist and the method used by detective <mark>Drury Lane</mark> to solve it must have garnered a lot of favor from readers.  \\n<br>\\nBut on the other hand, I wonder, \\"Is it right for the case to be handled like this?\\"  \\nA handling method similar to ```Murder on the Orient Express```.  \\n<br>\\nIt\'s similar to <mark>Crooked House</mark>.\\n"}')}}]);